CREATE FUNCTION public.settle_paystark_payment(_reference text,_amount numeric,_provider_reference text DEFAULT NULL,_provider_data jsonb DEFAULT '{}') RETURNS TABLE(credited boolean,already_credited boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.payment_intents; w public.wallets; b numeric; BEGIN SELECT * INTO i FROM public.payment_intents WHERE reference=_reference AND provider='paystark' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Payment intent not found'; END IF; IF i.status='success' THEN RETURN QUERY SELECT false,true; RETURN; END IF; IF i.status<>'pending' OR _amount IS NULL OR _amount<>i.amount OR _amount<=0 OR i.currency<>'NGN' THEN RAISE EXCEPTION 'Invalid settlement'; END IF; SELECT * INTO w FROM public.wallets WHERE user_id=i.user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF; UPDATE public.wallets SET balance=balance+_amount,updated_at=now() WHERE id=w.id RETURNING balance INTO b; UPDATE public.payment_intents SET status='success',provider_reference=COALESCE(_provider_reference,provider_reference),raw=raw||jsonb_build_object('settlement',_provider_data),updated_at=now() WHERE id=i.id; INSERT INTO public.wallet_transactions(wallet_id,user_id,type,amount,balance_after,status,provider,reference,description,metadata) VALUES(w.id,i.user_id,'credit',_amount,b,'success','paystark',_reference,'Wallet funded via PayStark',jsonb_build_object('provider_reference',_provider_reference)); RETURN QUERY SELECT true,false; END $$;
REVOKE ALL ON FUNCTION public.settle_paystark_payment(text,numeric,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.settle_paystark_payment(text,numeric,text,jsonb) TO service_role;